const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const chiangMai = ee.Geometry.Point([98.9853, 18.7883]);
    const aoi = chiangMai.buffer(5000); // 5km buffer around the city center
    const dateStartMar = '2024-03-01';
    const dateEndMar = '2024-03-31';
    const dateStartMay = '2024-05-01';
    const dateEndMay = '2024-05-31';
    const collectionName = 'MODIS/061/MCD19A2_GRANULES';
    const bandName = 'Optical_Depth_0550';

    // 2. Data Acquisition & Processing Function
    const getMonthlyAOD = function(startDate, endDate) {
        let collection = ee.ImageCollection(collectionName)
            .filterBounds(aoi)
            .filterDate(startDate, endDate)
            .select([bandName, 'AOD_QA']);

        // Check if collection is empty
        if (collection.size().getInfo() === 0) {
            return { image: null, size: 0, validPixels: 0 };
        }

        const maskAOD = function(image) {
            const qa = image.select('AOD_QA');
            // Bit 0-3 for AOD quality. 0000=Best, 0001=Good.
            // We create a mask for pixels with quality 0 or 1.
            const qualityMask = qa.bitwiseAnd(0x000F).lte(1);
            // Apply scale factor of 0.001 to the AOD band
            const aod = image.select(bandName).multiply(0.001);
            return aod.updateMask(qualityMask).copyProperties(image, ['system:time_start']);
        };

        const maskedCollection = collection.map(maskAOD);
        const meanImage = maskedCollection.mean();

        // Check for valid pixels after masking
        const pixelCount = meanImage.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: 1000,
            maxPixels: 1e9
        }).get(bandName).getInfo();

        return { image: meanImage, size: collection.size().getInfo(), validPixels: pixelCount };
    };

    // 3. Calculation
    const aodDataMar = getMonthlyAOD(dateStartMar, dateEndMar);
    const aodDataMay = getMonthlyAOD(dateStartMay, dateEndMay);

    // 4. Validation & Final Answer
    console.log(`March 2024: Found ${aodDataMar.size} images.`);
    console.log(`May 2024: Found ${aodDataMay.size} images.`);

    if (aodDataMar.size === 0 || aodDataMay.size === 0) {
        console.log("Evidence: One or both time periods had no images.");
        console.log("A"); // C1
        return;
    }

    console.log(`March 2024: Valid pixels after QA masking: ${aodDataMar.validPixels}.`);
    console.log(`May 2024: Valid pixels after QA masking: ${aodDataMay.validPixels}.`);

    if (aodDataMar.validPixels === 0 || aodDataMay.validPixels === 0) {
        console.log("Evidence: One or both periods had no valid pixels after cloud/quality masking.");
        console.log("B"); // C2
        return;
    }

    const aodMar = aodDataMar.image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    }).get(bandName).getInfo();

    const aodMay = aodDataMay.image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    }).get(bandName).getInfo();

    if (aodMar === null || aodMay === null || isNaN(aodMar) || isNaN(aodMay)) {
        console.log("Evidence: Calculation failed, result is null or NaN.");
        console.log(`March AOD: ${aodMar}`);
        console.log(`May AOD: ${aodMay}`);
        console.log("C3");
        return;
    }

    console.log(`Evidence: March 2024 mean AOD: ${aodMar.toFixed(3)}`);
    console.log(`Evidence: May 2024 mean AOD: ${aodMay.toFixed(3)}`);

    if (aodMar > aodMay) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
